window.docContents[90].resolve({"/Strong-multiplicity-one/#Strong-Multiplicity-One-___-Lean-blueprint--Strong-multiplicity-one":{"contents":"(Strong multiplicity one — Miyake 4.6.8 / 4.6.12.) Two newforms whose Hecke\neigenvalues  agree for all but finitely many  are equal (up to a\nconstant multiple) — a newform is determined by almost all of its eigenvalues\n(, ). In LeanModularForms the\nheadline is the axiom-clean ,\nrefining  (Theorem 4.6.12, made\nunconditional on the character-space isotypic decomposition).\n\nIf two eigenforms share eigenvalues at almost all , their difference lies in\nthe old subspace () yet is itself new, so it is\nforced to vanish: the old part of a form sharing a new form's eigenvalues is zero\n(), and a newform is not in\nthe extended old subspace ().\nHence the two forms agree up to the constant fixed by the shared first\ncoefficient.\n\n","context":"Strong Multiplicity One — Lean blueprint","header":"2. Strong multiplicity one","id":"/Strong-multiplicity-one/#Strong-Multiplicity-One-___-Lean-blueprint--Strong-multiplicity-one"}});